<?php
require_once __DIR__.'/../../includes/doctor_page.php';require_once __DIR__.'/../../includes/doctor_clinical_service.php';
$service=new DoctorClinicalService(getDB(),current_user());$pageTitle='Patient & Consultation Records';$error='';$overview=null;$patients=[];
$text=static fn($key)=>is_string($_GET[$key]??'')?trim($_GET[$key]??''):'';
$search=$text('search');$role=$text('role');$identifier=$text('identifier');$tab=$text('tab')?:'overview';
if(!in_array($tab,['overview','medical','consultations','notes','followups'],true))$tab='overview';
$raw=$_POST['patient_user_id']??$_GET['patient']??'0';$patient=is_scalar($raw)&&ctype_digit((string)$raw)?(int)$raw:0;
if($raw!=='0'&&!$patient){http_response_code(400);$error='Choose a valid patient from the directory.';}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify_or_die();try{$service->save($_POST);set_flash('success','Physician encounter saved with author and audit history.');redirect('patients.php?patient='.$patient.'&tab=consultations');}catch(InvalidArgumentException|RuntimeException $e){$error=$e instanceof PDOException?'Clinical data could not be saved. Please retry.':$e->getMessage();http_response_code(422);}}
try{$patients=$service->patients($search,$role,$identifier);if($patient)$overview=$service->overview($patient);}catch(InvalidArgumentException $e){http_response_code(404);$error=$e->getMessage();}catch(PDOException $e){http_response_code(503);error_log('Doctor patient source unavailable SQLSTATE='.$e->getCode());$error='Patient information is temporarily unavailable. Please reload; missing data is not an empty history.';}
$records=$overview['consultations']??[];
?>
<!doctype html><html lang="en"><head><?php include __DIR__.'/../../includes/head.php'; ?></head><body><div class="app-wrapper"><?php include __DIR__.'/../../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../../components/navbar.php'; ?>
<main class="content-area clinical-workspace" id="mainContent"><header class="clinical-hero"><span class="clinical-kicker">Patient care</span><h1 class="h3 mt-2">Patient &amp; Consultation Records</h1><p>Student and Teacher clinical history in one workspace. Physician revisions preserve nursing documentation and record authorship.</p></header>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif; ?>
<section class="clinical-panel"><h2>Find a patient</h2><form method="get" class="row g-2 align-items-end"><div class="col-12 col-md-4"><label for="clinical-search" class="form-label">Name or institutional ID</label><input id="clinical-search" name="search" class="form-control" value="<?=e($search)?>" maxlength="100"></div><div class="col-6 col-md-3"><label for="clinical-role" class="form-label">Patient type</label><select id="clinical-role" name="role" class="form-select"><option value="">All patients</option><?php foreach(['student','teacher'] as $type): ?><option value="<?=$type?>" <?=$role===$type?'selected':''?>><?=ucfirst($type)?></option><?php endforeach; ?></select></div><div class="col-6 col-md-3"><label for="clinical-id" class="form-label">Institutional ID</label><input id="clinical-id" name="identifier" class="form-control" value="<?=e($identifier)?>" maxlength="100"></div><div class="col-12 col-md-2"><button class="btn btn-success w-100">Search</button></div></form>
<div class="table-responsive mt-3"><table class="table align-middle"><thead><tr><th>Patient</th><th>Type</th><th>Institutional ID</th><th>Clinical workspace</th></tr></thead><tbody><?php foreach($patients as $p): ?><tr><td><?=e($p['first_name'].' '.$p['last_name'])?></td><td><?=e(ucfirst($p['role']))?></td><td><?=e($p['identifier']??'Not recorded')?></td><td><a class="btn btn-sm btn-outline-success" href="patients.php?<?=e(http_build_query(['patient'=>$p['id'],'search'=>$search,'role'=>$role,'identifier'=>$identifier]))?>">View clinical records</a></td></tr><?php endforeach; ?><?php if(!$patients&&!$error): ?><tr><td colspan="4">No matching patients. Try another name or institutional ID.</td></tr><?php endif; ?></tbody></table></div><p class="small text-muted mb-0">Up to 50 matches. Refine your search to find additional patients.</p></section>
<?php if($overview): $person=$overview['patient']; ?>
<section class="clinical-panel" id="selectedPatient" data-patient-id="<?=$patient?>"><h2><?=e($person['first_name'].' '.$person['last_name'])?></h2><p><?=e(ucfirst($person['role']))?> · <?=e($person['identifier']??'Institutional ID not recorded')?></p>
<nav class="clinical-tabs" aria-label="Patient record sections"><?php foreach(['overview'=>'Clinical overview','medical'=>'Medical history','consultations'=>'Consultation history','notes'=>'Clinical notes','followups'=>'Follow-ups'] as $key=>$label): ?><a href="patients.php?patient=<?=$patient?>&amp;tab=<?=$key?>" <?=$tab===$key?'aria-current="page"':''?>><?=$label?></a><?php endforeach; ?></nav>
<?php if($tab==='overview'): ?><dl><dt>Blood type</dt><dd><?=e($person['blood_type']?:'Not recorded')?></dd><dt>Recorded allergies</dt><dd><?=e($person['allergies']?:'Not recorded — confirm with the patient')?></dd><dt>Consultations loaded</dt><dd><?=count($records)?> (up to 50)</dd></dl><a class="btn btn-outline-success" href="patients.php?patient=<?=$patient?>&amp;tab=notes">Document physician consultation</a>
<?php elseif($tab==='medical'): ?><h3 class="h6">Medical history documents</h3><?php foreach($overview['documents'] as $document): ?><article class="border rounded p-3 mb-2"><strong><?=e($document['description']?:'Clinical attachment')?></strong><p class="small"><?=e($document['uploaded_at'])?> · <?=e($document['file_type'])?></p><a class="btn btn-sm btn-outline-success" href="<?=e(app_url('api/clinical.php').'?'.http_build_query(['action'=>'document','patient_user_id'=>$patient,'id'=>$document['id']]))?>">Download authorized document</a></article><?php endforeach; ?><?php if(!$overview['documents']): ?><p class="text-muted">No medical documents recorded for this patient.</p><?php endif; ?><p class="small text-muted">See Consultation history for recorded diagnoses and treatment.</p>
<?php elseif(in_array($tab,['consultations','followups'],true)): $display=$tab==='followups'?array_filter($records,static fn($r)=>!empty($r['follow_up_date'])):$records; ?><?php foreach($display as $r): ?><details class="border rounded p-3 mb-3"><summary><?=e($tab==='followups'?$r['follow_up_date']:$r['consultation_date'])?> · <?=e($r['chief_complaint'])?></summary><dl class="mt-3"><?php foreach(['diagnosis','treatment','prescription','remarks','follow_up_date'] as $field): ?><dt><?=e(ucwords(str_replace('_',' ',$field)))?></dt><dd><?=nl2br(e($r[$field]?:'Not recorded'))?></dd><?php endforeach; ?></dl><small>Consultation #<?=(int)$r['id']?> · <?=empty($r['clinician_user_id'])?'Nursing / legacy documentation':'Physician encounter'?></small></details><?php endforeach; ?><?php if(!$display): ?><p class="text-muted">No <?=$tab==='followups'?'follow-up dates':'consultations'?> recorded in the loaded history.</p><?php endif; ?>
<?php else: ?>
<h3 class="h6">Physician notes and consultation</h3><p class="small text-muted">Review all findings before saving. MICA cannot approve treatment.</p>
<?php $noted=array_filter($records,static fn($record)=>trim((string)($record['remarks']??''))!==''); ?><details class="border rounded p-3 mb-3"><summary>Recorded clinical notes (<?=count($noted)?>)</summary><?php foreach($noted as $note): ?><article class="border-bottom py-3"><strong><?=e($note['consultation_date'])?> · <?=empty($note['clinician_user_id'])?'Nursing / legacy note':'Physician note'?></strong><p class="mb-0"><?=nl2br(e($note['remarks']))?></p></article><?php endforeach; ?><?php if(!$noted): ?><p class="text-muted mt-3">No clinical notes recorded in the loaded history.</p><?php endif; ?></details>
<?php $forms=[['id'=>0,'record_version'=>0]];foreach($records as $r)if((int)$r['clinician_user_id']===(int)current_user()['id'])$forms[]=$r;foreach($forms as $r): ?>
<details class="border rounded p-3 mb-3" <?=$r['id']?'':'open'?>><summary><?=$r['id']?'Revise your encounter #'.(int)$r['id']:'New physician encounter'?></summary><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="patient_user_id" value="<?=$patient?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="record_version" value="<?=(int)$r['record_version']?>">
<?php if($_SERVER['REQUEST_METHOD']==='POST'&&(int)($_POST['id']??0)===(int)$r['id'])foreach(['chief_complaint','diagnosis','treatment','prescription','remarks','follow_up_date'] as $field)if(is_string($_POST[$field]??null))$r[$field]=$_POST[$field]; ?>
<?php foreach(['chief_complaint'=>'Chief complaint','diagnosis'=>'Findings / diagnosis','treatment'=>'Treatment decision','prescription'=>'Prescription / instructions','remarks'=>'Clinical notes'] as $field=>$label): ?><label class="form-label mt-2" for="record-<?=$r['id']?>-<?=$field?>"><?=$label?></label><textarea class="form-control" id="record-<?=$r['id']?>-<?=$field?>" name="<?=$field?>" maxlength="<?=in_array($field,['chief_complaint','diagnosis'],true)?255:5000?>" <?=$field==='chief_complaint'?'required':''?>><?=e($r[$field]??'')?></textarea><?php endforeach; ?><label class="form-label mt-3" for="follow-<?=$r['id']?>">Follow-up date (optional)</label><input class="form-control" type="date" id="follow-<?=$r['id']?>" name="follow_up_date" value="<?=e($r['follow_up_date']??'')?>"><button class="btn btn-success mt-3">Confirm and save physician encounter</button></form></details><?php endforeach; ?>
<section class="border rounded p-3"><h3 class="h6">MICA clinical assistant</h3><p class="small">Ask the floating MICA assistant: “Draft patient #<?=$patient?> summary”, or prepare a draft here. The draft uses recorded history and requires your review. It is not saved as clinical documentation.</p><form method="post" action="<?=e(app_url('api/clinical.php'))?>" data-clinical-draft><?=csrf_field()?><input type="hidden" name="action" value="draft"><input type="hidden" name="patient_user_id" value="<?=$patient?>"><button class="btn btn-outline-success">Prepare history draft</button></form><pre class="mt-3 small" style="white-space:pre-wrap;overflow-wrap:anywhere" id="clinicalDraft" role="status" hidden></pre></section>
<?php endif; ?></section>
<?php elseif(!$patient&&!$error): ?><section class="clinical-panel"><p class="mb-0 text-muted">Select “View clinical records” to open the authorized patient workspace.</p></section><?php endif; ?>
